import{_ as a,c as o,o as i,j as e,ae as r,a as s}from"./chunks/framework.BGWP4WZ_.js";const n="/py-xiaozhi/assets/logo.DUF47VPs.png",f=JSON.parse('{"title":"xiaozhi-esp32-server","description":"Lightweight and efficient voice interaction server based on ESP32","frontmatter":{"title":"xiaozhi-esp32-server","description":"Lightweight and efficient voice interaction server based on ESP32"},"headers":[],"relativePath":"ecosystem/projects/xiaozhi-esp32-server/index.md","filePath":"ecosystem/projects/xiaozhi-esp32-server/index.md"}'),l={name:"ecosystem/projects/xiaozhi-esp32-server/index.md"};function c(d,t,p,h,u,m){return i(),o("div",null,t[0]||(t[0]=[e("h1",{id:"xiaozhi-esp32-server",tabindex:"-1"},[s("xiaozhi-esp32-server "),e("a",{class:"header-anchor",href:"#xiaozhi-esp32-server","aria-label":'Permalink to "xiaozhi-esp32-server"'},"​")],-1),e("div",{class:"project-header"},[e("div",{class:"project-logo"},[e("img",{src:n,alt:"xiaozhi-esp32-server Logo",onerror:"this.src='/py-xiaozhi/images/logo.png'; this.onerror=null;"})]),e("div",{class:"project-badges"},[e("span",{class:"badge platform"},"ESP32"),e("span",{class:"badge language"},"Python"),e("span",{class:"badge status"},"Active Development")])],-1),r('<div class="project-intro"><p>xiaozhi-esp32-server is a backend service for the open-source smart hardware project <a href="https://github.com/78/xiaozhi-esp32" target="_blank">xiaozhi-esp32</a>. It is implemented in Python according to the <a href="https://ccnphfhqs21z.feishu.cn/wiki/M0XiwldO9iJwHikpXD5cEx71nKh" target="_blank">Xiaozhi Communication Protocol</a>, helping you quickly set up your own Xiaozhi server.</p></div><h2 id="target-audience" tabindex="-1">Target Audience <a class="header-anchor" href="#target-audience" aria-label="Permalink to &quot;Target Audience&quot;">​</a></h2><p>This project is intended for use with ESP32 hardware devices. If you have already purchased ESP32 hardware, successfully connected to the backend service deployed by Xiage, and want to set up your own independent <code>xiaozhi-esp32</code> backend, this project is for you.</p><div class="warning-box"><h3>⚠️ Important Notice</h3><ol><li>This project is open-source software and has no commercial relationship with any third-party API service providers (including but not limited to speech recognition, LLMs, TTS platforms, etc.). It does not guarantee the quality or financial security of their services. Users are advised to choose providers with proper business licenses and carefully read their service agreements and privacy policies. This software does not host any account keys, does not participate in financial transactions, and does not bear any risk of fund loss.</li><li>This project is relatively new and has not passed network security assessments. Do not use it in production environments. If you deploy this project on a public network for learning purposes, be sure to enable protection in the <code>config.yaml</code> configuration file.</li></ol></div><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><div class="features-container"><div class="feature-item"><div class="feature-icon">🔄</div><h3>Communication Protocol</h3><p>Based on the <code>xiaozhi-esp32</code> protocol, data exchange via WebSocket</p></div><div class="feature-item"><div class="feature-icon">💬</div><h3>Dialogue Interaction</h3><p>Supports wake-up dialogue, manual dialogue, real-time interruption, and auto-sleep after inactivity</p></div><div class="feature-item"><div class="feature-icon">🧠</div><h3>Intent Recognition</h3><p>Supports LLM-based intent recognition and function call, reducing hardcoded intent logic</p></div><div class="feature-item"><div class="feature-icon">🌐</div><h3>Multilingual Recognition</h3><p>Supports Mandarin, Cantonese, English, Japanese, Korean (default: FunASR)</p></div><div class="feature-item"><div class="feature-icon">🤖</div><h3>LLM Module</h3><p>Flexible LLM module switching. Default: ChatGLMLLM. Also supports Alibaba Bailian, DeepSeek, Ollama, etc.</p></div><div class="feature-item"><div class="feature-icon">🔊</div><h3>TTS Module</h3><p>Supports EdgeTTS (default), Doubao TTS, and more, meeting various speech synthesis needs</p></div><div class="feature-item"><div class="feature-icon">📝</div><h3>Memory Function</h3><p>Supports long-term memory, local summary memory, and no-memory modes for different scenarios</p></div><div class="feature-item"><div class="feature-icon">🏠</div><h3>IOT Functionality</h3><p>Manage registered IOT devices and control smart home devices based on dialogue context</p></div><div class="feature-item"><div class="feature-icon">🖥️</div><h3>Smart Console</h3><p>Web management interface for agent management, user management, system configuration, etc.</p></div></div><h2 id="deployment-methods" tabindex="-1">Deployment Methods <a class="header-anchor" href="#deployment-methods" aria-label="Permalink to &quot;Deployment Methods&quot;">​</a></h2><p>This project provides two deployment methods. Choose according to your needs:</p><div class="deployment-table"><table><thead><tr><th>Deployment Method</th><th>Features</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>Minimal Installation</strong></td><td>Smart dialogue, IOT functionality, data stored in config files</td><td>Low-resource environments, no database required</td></tr><tr><td><strong>Full Module Installation</strong></td><td>Smart dialogue, IOT, OTA, Smart Console, data stored in database</td><td>Full feature experience</td></tr></tbody></table></div><p>For detailed deployment documentation, see:</p><ul><li><a href="https://github.com/xinnan-tech/xiaozhi-esp32-server/blob/main/docs/Deployment.md" target="_blank" rel="noreferrer">Docker Deployment Guide</a></li><li><a href="https://github.com/xinnan-tech/xiaozhi-esp32-server/blob/main/docs/Deployment_all.md" target="_blank" rel="noreferrer">Source Code Deployment Guide</a></li></ul><h2 id="supported-platforms" tabindex="-1">Supported Platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported Platforms&quot;">​</a></h2><p>xiaozhi-esp32-server supports a wide range of third-party platforms and components:</p><h3 id="llm-language-models" tabindex="-1">LLM Language Models <a class="header-anchor" href="#llm-language-models" aria-label="Permalink to &quot;LLM Language Models&quot;">​</a></h3><div class="platform-item"><h4>API Integration</h4><p><strong>Supported Platforms:</strong> Alibaba Bailian, Doubao, DeepSeek, Zhipu ChatGLM, Gemini, Ollama, Dify, Fastgpt, Coze</p><p><strong>Free Platforms:</strong> Zhipu ChatGLM, Gemini</p><p><em>Any LLM supporting the OpenAI API can be integrated</em></p></div><h3 id="tts-speech-synthesis" tabindex="-1">TTS Speech Synthesis <a class="header-anchor" href="#tts-speech-synthesis" aria-label="Permalink to &quot;TTS Speech Synthesis&quot;">​</a></h3><div class="platform-item"><h4>API Integration</h4><p><strong>Supported Platforms:</strong> EdgeTTS, Doubao TTS, Tencent Cloud, Alibaba Cloud TTS, CosyVoiceSiliconflow, TTS302AI, CozeCnTTS, GizwitsTTS, ACGNTTS, OpenAITTS</p><p><strong>Free Platforms:</strong> EdgeTTS, CosyVoiceSiliconflow (partial)</p><h4>Local Services</h4><p><strong>Supported Platforms:</strong> FishSpeech, GPT_SOVITS_V2, GPT_SOVITS_V3, MinimaxTTS</p><p><strong>Free Platforms:</strong> FishSpeech, GPT_SOVITS_V2, GPT_SOVITS_V3, MinimaxTTS</p></div><h3 id="asr-speech-recognition" tabindex="-1">ASR Speech Recognition <a class="header-anchor" href="#asr-speech-recognition" aria-label="Permalink to &quot;ASR Speech Recognition&quot;">​</a></h3><div class="platform-item"><h4>API Integration</h4><p><strong>Supported Platforms:</strong> DoubaoASR</p><h4>Local Services</h4><p><strong>Supported Platforms:</strong> FunASR, SherpaASR</p><p><strong>Free Platforms:</strong> FunASR, SherpaASR</p></div><h3 id="more-components" tabindex="-1">More Components <a class="header-anchor" href="#more-components" aria-label="Permalink to &quot;More Components&quot;">​</a></h3><ul><li><strong>VAD Voice Activity Detection</strong>: Supports SileroVAD (local, free)</li><li><strong>Memory Storage</strong>: Supports mem0ai (1000 times/month), mem_local_short (local summary, free)</li><li><strong>Intent Recognition</strong>: Supports intent_llm (LLM-based intent recognition), function_call (intent via LLM function call)</li></ul><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>xiaozhi-esp32-server is an active open-source project. Contributions and feedback are welcome:</p><ul><li><a href="https://github.com/xinnan-tech/xiaozhi-esp32-server" target="_blank" rel="noreferrer">GitHub Repository</a></li><li><a href="https://github.com/xinnan-tech/xiaozhi-esp32-server/issues" target="_blank" rel="noreferrer">Issue Tracker</a></li><li><a href="https://github.com/xinnan-tech/xiaozhi-esp32-server/blob/main/docs/contributor_open_letter.md" target="_blank" rel="noreferrer">Open Letter to Developers</a></li></ul>',24)]))}const v=a(l,[["render",c]]);export{f as __pageData,v as default};
